pages["signup.html"]=("Create Account | D3DDD Portal","Create a D3DDD client portal account.",'''<div class="auth"><div id="demo-banner"></div><p class="eyebrow">Client portal</p><h2>Create account</h2><form id="signup-form"><label for="sn">Full name</label><input id="sn" required><label for="sc">Company (optional)</label><input id="sc"><label for="sph">Phone (optional)</label><input id="sph" type="tel"><label for="se">Email</label><input id="se" type="email" required autocomplete="email"><label for="sp">Password (min 8)</label><input id="sp" type="password" minlength="8" required autocomplete="new-password"><button class="btn" style="margin-top:18px;width:100%" type="submit">Create account</button><p class="msg" id="msg"></p></form><p style="margin-top:16px;font-size:14px">Already registered? <a href="login.html"><u>Log in</u></a></p></div>''',"",'<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2" defer></script><script src="assets/portal.js" defer></script>',True)
